userscript.function:

if (Sepoa.request.MODE == 'POPUP') {
    callFunction('ECT_101', 'setConfig', [{
        TYPE: 'CONTRACT',
        FILTER: {}
    }]);

    const data = {
        view: 'VIEW',
        data: {
            CONT_NO: Sepoa.request.CONT_NO,
            CONT_GL_SEQ: Sepoa.request.CONT_GL_SEQ
        }
    };

    changeView(data);

    return;
}

if ($sObject.alias == $sObject.aliasCode) {
    Alert('not found type data');
    return;
}

var filterOptions = {};
for (var i in Sepoa.request) {
    if (i.indexOf("F_") == 0) {
        filterOptions[i] = Sepoa.request[i];
    }
}

callFunction('ECT_101', 'setConfig', [{
    TYPE: $sObject.alias.replace($sObject.aliasCode + '_', ''),
    FILTER: filterOptions
}])


let cellID;
let id = data.view?.toUpperCase() || ''
if (id === 'EDITOR') {
    cellID = 'FORM';
} else if (['VIEW', 'SIGN', 'APPROVAL', 'SAVE', 'COMPLETE', 'TERMINATION', 'REVIEW', 'PREVIEW'].includes(id)) {
    cellID = 'MODULE';
} else {
    cellID = id;
}

if (id == "EDITOR") {
    if (['SRM', 'SEAL'].includes(data.data.DATA_SOURCE)) {
        $share.config = {
            document: {
                CONT_TYPE: (data.data.CONT_TYPE || "E"), //B: Business, E: Employee
                CONT_NO: data.data.CONT_NO,
                CONT_GL_SEQ: data.data.CONT_GL_SEQ
            }
        }

        if ($share.childScreen && $share.childScreen.FORM) {
            $share.childScreen.FORM.fn.doOpenDocument($share.config);
        }
    } else if (data.data.DATA_SOURCE == 'NEW') {
        $share.config = {
            document: {
                CONT_TYPE: 'NEW'
            }
        };

        if (sUtils.string.isBlank(data.data.CONT_NO) === false) {
            $share.config = {
                document: {
                    CONT_TYPE: data.data.CONT_TYPE,
                    CONT_NO: data.data.CONT_NO,
                    CONT_GL_SEQ: data.data.CONT_GL_SEQ
                }
            }
        }

        if ($share.childScreen && $share.childScreen.FORM) {
            $share.childScreen.FORM.fn.doOpenDocument($share.config);
        }
    } else {
        let params = {
            CONT_NO: data.data.CONT_NO,
            CONT_GL_SEQ: data.data.CONT_GL_SEQ,
            CONT_TYPE: data.data.CONT_TYPE
        };

        if (["RA", "F"].includes(data.data.CONT_STATUS)) {
            if ("RA" == data.data.CONT_STATUS) {
                params["CONT_MODULE"] = "REVIEW_DONE";
            } else if ("F" == data.data.CONT_STATUS) {
                params["CONT_MODULE"] = "APPROVAL_DONE";
            }

        } else {
            params["CONT_MODULE"] = "EDITOR";
        }

        sUtils.popup.modal({
            url: window.CONTEXT_NAME + '/EmployeeContract/Module/EmployeeContractModuleLayout.sux',
            params: params,
            title: sUtils.cache.text.get('POA_CONTRACT.TITLE_EDITOR')
        });
        return;
    }
} else if (id == "LIST") {
    delete $share.config;
    callFunction("ECT_102", 'doQuery', []);
} else {
    $share.config = {
        module: {
            WORK_TYPE: 'C', // T: template, C:contract
            CONT_TYPE: (data.data.CONT_TYPE || "E"), // B: Business, E: Employee
            CONT_MODULE: id
        },
        document: {
            CONT_TYPE: (data.data.CONT_TYPE || "E"), //B: Business, E: Employee
            CONT_NO: data.data.CONT_NO,
            CONT_GL_SEQ: data.data.CONT_GL_SEQ
        },
        editor: {
            header: []
        }
    }
    if ($share.childScreen && $share.childScreen.MODULE) {
        $share.childScreen.MODULE.fn.doOpenDocument($share.config);
    }
}

var cells = carouselObj.cells(cellID);
cells.setActive();
